using System.Text.Json.Nodes;
using System.Text.Json;
using System.Net;

public static class LiveSupportEndpoints
{
    static async Task<JsonObject> Body(HttpContext c) => await c.Request.ReadFromJsonAsync<JsonObject>()??throw new ArgumentException("İşlem bilgisi gerekli.");
    static string Value(JsonObject b,string key)=>b[key]?.ToString()??"";
    static IResult Denied()=>Results.Json(new{error="Bu canlı destek işlemi için yetkiniz yok."},statusCode:403);
    public static void Map(WebApplication app)
    {
        app.MapGet("/admin/live-support",(HttpContext c)=>LiveSupportStore.Staff(c.User)?Results.Content(Page(),"text/html; charset=utf-8"):Denied()).RequireAuthorization();
        app.MapGet("/api/live-support/status",(HttpContext c,LiveSupportStore store,SupportTranslation translator)=>Results.Json(store.Status(c,translator))).RequireRateLimiting("support-read");
        app.MapPost("/api/live-support/session",async(HttpContext c,LiveSupportStore store)=>
        {var b=await Body(c);var actor=LiveSupportStore.EnsureActor(c);if(LiveSupportStore.Staff(c.User))return Denied();var name=c.User.Identity?.IsAuthenticated==true?AccessControl.DisplayName(c.User):Value(b,"name");if(name.Contains('@'))name="Ziyaretçi";return Results.Json(store.Open(actor,name,Value(b,"language")));}).RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/presence",async(HttpContext c,LiveSupportStore store)=>
        {if(!LiveSupportStore.Respond(c.User))return Denied();var b=await Body(c);store.Presence(LiveSupportStore.Actor(c),LiveSupportStore.AgentName(c.User),Value(b,"language"),b["ready"]?.GetValue<bool>()!=false,Value(b,"client"));return Results.Json(new{ok=true});}).RequireAuthorization().RequireRateLimiting("support-write");
        app.MapGet("/api/live-support/state",(HttpContext c,LiveSupportStore store)=>
        {var actor=LiveSupportStore.Actor(c);if(actor=="")return c.Request.Query["thread"].ToString()!=""?Denied():Results.Json(new{online=store.Available().Length>0,messages=Array.Empty<object>(),signals=Array.Empty<object>()});long.TryParse(c.Request.Query["since"],out var since);return Results.Json(store.State(actor,LiveSupportStore.Staff(c.User),c.Request.Query["thread"].ToString(),c.Request.Query["language"].ToString(),since));}).RequireRateLimiting("support-read");
        app.MapPost("/api/live-support/{id}/message",async(string id,HttpContext c,LiveSupportStore store,SupportTranslation translator)=>
        {var b=await Body(c);var staff=LiveSupportStore.Staff(c.User);if(staff&&!LiveSupportStore.Respond(c.User))return Denied();var actor=LiveSupportStore.Actor(c);if(actor=="")return Denied();var m=store.Add(id,actor,staff,staff?LiveSupportStore.AgentName(c.User):"Ziyaretçi",Value(b,"text"),Value(b,"language"),Value(b,"clientId"),allowTranslation:b["translate"]?.GetValue<bool>()==true);
            var target=store.TargetLanguage(id,staff);var translation=m.AllowTranslation?(m.Translations.GetValueOrDefault(target)??await translator.Translate(m.Text,m.Language,target,c.RequestAborted,store.TranslationContext(id,m.Id,actor,staff))):null;if(translation!=null)store.TranslateResult(id,m.Id,target,translation);return Results.Json(new{id=m.Id,translated=translation!=null});}).RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/translate/{message}",async(string id,string message,HttpContext c,LiveSupportStore store,SupportTranslation translator)=>
        {var b=await Body(c);var target=LiveSupportStore.Language(Value(b,"language"));var actor=LiveSupportStore.Actor(c);if(actor=="")return Denied();store.Limit(actor+":translate",60);var m=store.TranslationInput(id,message,actor,LiveSupportStore.Staff(c.User),target);var text=m.Allowed?(m.Cached??await translator.Translate(m.Text,m.Language,target,c.RequestAborted,store.TranslationContext(id,message,actor,LiveSupportStore.Staff(c.User)))):null;if(text!=null)store.TranslateResult(id,message,target,text);return Results.Json(new{translation=text,available=text!=null});}).RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/read",(string id,HttpContext c,LiveSupportStore store)=>{store.Read(id,LiveSupportStore.Actor(c),LiveSupportStore.Staff(c.User));return Results.Json(new{ok=true});}).RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/typing",(string id,HttpContext c,LiveSupportStore store)=>{if(LiveSupportStore.Staff(c.User)&&!LiveSupportStore.Respond(c.User))return Denied();store.Typing(id,LiveSupportStore.Actor(c),LiveSupportStore.Staff(c.User));return Results.Json(new{ok=true});}).RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/assign",async(string id,HttpContext c,LiveSupportStore store)=>{if(!LiveSupportStore.Respond(c.User))return Denied();var b=await Body(c);var target=Value(b,"agent");store.Assign(id,LiveSupportStore.Actor(c),target=="self"?LiveSupportStore.Actor(c):target,LiveSupportStore.AgentName(c.User));return Results.Json(new{ok=true});}).RequireAuthorization().RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/close",(string id,HttpContext c,LiveSupportStore store)=>{if(!LiveSupportStore.Respond(c.User))return Denied();store.Close(id,LiveSupportStore.Actor(c));return Results.Json(new{ok=true});}).RequireAuthorization().RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/upload",async(string id,HttpContext c,LiveSupportStore store)=>
        {if(LiveSupportStore.Staff(c.User)&&!LiveSupportStore.Respond(c.User))return Denied();if(c.Request.ContentLength>6*1024*1024)return Results.Json(new{error="Dosya en fazla 5 MB olabilir."},statusCode:413);var form=await c.Request.ReadFormAsync(c.RequestAborted);var upload=form.Files.GetFile("file")??throw new ArgumentException("Dosya seçin.");return Results.Json(await store.Upload(id,c,upload));}).RequireRateLimiting("support-write");
        app.MapGet("/api/live-support/{id}/file/{message}",(string id,string message,HttpContext c,LiveSupportStore store)=>{var f=store.Attachment(id,message,LiveSupportStore.Actor(c),LiveSupportStore.Staff(c.User));c.Response.Headers["Content-Security-Policy"]="sandbox";return Results.File(f.Path,f.Type,f.Name);}).RequireRateLimiting("support-read");
        app.MapPost("/api/live-support/{id}/call",async(string id,HttpContext c,LiveSupportStore store)=>{if(!LiveSupportStore.Respond(c.User))return Denied();var b=await Body(c);return Results.Json(store.StartCall(id,LiveSupportStore.Actor(c),Value(b,"kind")));}).RequireAuthorization().RequireRateLimiting("support-write");
        app.MapPost("/api/live-support/{id}/signal",async(string id,HttpContext c,LiveSupportStore store)=>{var b=await Body(c);if(LiveSupportStore.Staff(c.User)&&!LiveSupportStore.Respond(c.User))return Denied();store.Signal(id,LiveSupportStore.Actor(c),LiveSupportStore.Staff(c.User),Value(b,"call"),Value(b,"kind"),Value(b,"payload"));return Results.Json(new{ok=true});}).RequireRateLimiting("support-write");
        app.MapGet("/api/live-support/rtc",(HttpContext c,IConfiguration config,LiveSupportStore store)=>
        {var actor=LiveSupportStore.Actor(c);if(actor==""||!store.CanUseRtc(c.Request.Query["thread"].ToString(),c.Request.Query["call"].ToString(),actor,LiveSupportStore.Staff(c.User)))return Denied();var servers=new List<object>{new{urls=new[]{"stun:stun.cloudflare.com:3478","stun:stun.l.google.com:19302"}}};var turn=config["LiveSupport:TurnUrl"]??"";var secret=config["LiveSupport:TurnSecret"]??"";var relay=(turn.StartsWith("turn:",StringComparison.Ordinal)||turn.StartsWith("turns:",StringComparison.Ordinal))&&secret!="";
            if(relay){var identity=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(actor)))[..12];var username=DateTimeOffset.UtcNow.AddMinutes(10).ToUnixTimeSeconds()+":"+identity;var credential=Convert.ToBase64String(System.Security.Cryptography.HMACSHA1.HashData(System.Text.Encoding.UTF8.GetBytes(secret),System.Text.Encoding.UTF8.GetBytes(username)));servers.Add(new{urls=new[]{turn},username,credential});}return Results.Json(new{iceServers=servers,relayConfigured=relay});}).RequireRateLimiting("support-read");
        app.MapGet("/api/live-support/settings",(HttpContext c,SupportTranslation translator)=>AccessControl.IsSuperAdmin(c.User)?Results.Json(new{translationReady=translator.Ready}):Denied()).RequireAuthorization();
        app.MapPost("/api/live-support/settings",async(HttpContext c,SupportTranslation translator)=>{if(!AccessControl.IsSuperAdmin(c.User))return Denied();var b=await Body(c);translator.Configure(Value(b,"apiKey"),b["remove"]?.GetValue<bool>()==true);return Results.Json(new{ok=true,translationReady=translator.Ready});}).RequireAuthorization().RequireRateLimiting("support-write");
    }
    static string Page()=>"""
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Canlı Destek | İnokskar</title><style>body{margin:0;background:#eff4fa;color:#172d47;font-family:Arial,sans-serif}header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 20px;border-bottom:1px solid #d8e4ef;background:#fff}h1{font-size:20px;margin:0}a{color:#175eaa;text-decoration:none;font-weight:700;font-size:14px}main{padding:12px;max-width:1280px;margin:auto}p{margin:8px 0;color:#52657a;font-size:13px}</style></head><body><header><h1>Canlı Destek</h1><a href="/admin">Yönetim paneli</a></header><main><div data-live-support-desk></div><noscript>Canlı destek için JavaScript'i etkinleştirin.</noscript></main></body></html>
""";
}
